def chain_follower(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict[chain[0]].append(chain[1])

    stack = [chain[0]]
    result = []

    while stack:
        current = stack.pop()
        result.append(current)

        next_items = chain_dict.get(current, [])
        if not next_items:
            break

        for item in next_items:
            stack.append(item)

    return ','.join(result)

# Example usage:
# print(chain_follower(['bbb', 'ccc']))  # Output: 'bbb, ccc'
